{
  "passageId": "giddens-beck-risk-society",
  "items": [
    {
      "id": "R1",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "기든스가 기존 두 입장의 설명상 한계를 지적하며 문제 삼으므로 비판 관계이다."
    },
    {
      "id": "R2",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "기존 입장의 이분법적 한계에 대한 대안으로 구조화 이론을 제시한다."
    },
    {
      "id": "R3",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "구조화 이론을 제시했다는 진술에 이어 그 이론의 구조관과 인간관을 구체적으로 설명한다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "언어 규칙과 언어 사용은 구조가 행위의 매개이자 결과물이라는 설명을 구체적으로 보여 주는 사례이다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "언어 규칙을 활용하고 변용하는 사례에서 인간의 일반적인 주체성을 이끌어 내므로 사례에서 일반 성질로 나아가는 구체화 관계이다."
    },
    {
      "id": "R6",
      "type": "CAUSE",
      "otherName": "",
      "reason": "성찰적 실천이 사회체계의 유지와 변형 및 재생산을 실제로 일으키는 작용을 설명한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "개인의 실천을 통한 사회체계 재생산이라는 설명을 행위의 지속 동력인 추상적 시스템으로 더 자세히 풀어낸다."
    },
    {
      "id": "R8",
      "type": "CAUSE",
      "otherName": "",
      "reason": "추상적 시스템이 사회체계 재생산에 필요한 개인 행위의 지속을 가능하게 하는 실제 동력으로 제시된다."
    },
    {
      "id": "R9",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "추상적 시스템의 구성 요소를 나열한 뒤 그중 상징적 표상의 의미와 사례 및 작용을 자세히 설명한다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "추상적 시스템의 구성 요소를 나열한 뒤 그중 전문가 체계의 의미와 사례 및 작용을 자세히 설명한다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "사회적 관계의 확장으로 낯선 환경과 타인을 접하게 되면서 불안과 불확실성이 발생한다."
    },
    {
      "id": "R12",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "낯선 환경과 타인에 대한 불안이라는 문제에 전문가 체계에 대한 믿음을 해소 방안으로 제시한다."
    },
    {
      "id": "R13",
      "type": "CAUSE",
      "otherName": "",
      "reason": "전문가 체계에 대한 믿음에 따른 불안 해소가 사회적 관계 맺기의 지속을 가능하게 하는 실제 작용을 설명한다."
    },
    {
      "id": "R14",
      "type": "CAUSE",
      "otherName": "",
      "reason": "사회적 관계 맺기와 개인 행위가 지속·반복됨으로써 사회체계가 재생산되는 결과로 이어진다."
    },
    {
      "id": "R15",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "현대 사회가 불확실한 환경인데도 인간은 구조를 능동적으로 재구성할 수 있다는 양보 관계이다."
    },
    {
      "id": "R16",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "구조화 이론의 내용을 인간의 주체성을 보여 준다는 관점에서 평가하여 이론적 의의를 부여한다."
    },
    {
      "id": "R17",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "산업 사회의 발전이 안정과 풍요에 기여하면서도 생존을 위협하는 위험을 낳았다는 동일 대상의 양면성을 제시한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞에서 제시한 산업 사회의 위험을 그 기원과 확산 범위 및 예측·통제의 한계로 세분하여 설명한다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "산업화가 낳은 위험으로 인해 안전과 생존 확보가 경제·정치의 최우선 과제로 부상하는 사회적 변화가 발생한다."
    },
    {
      "id": "R20",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "안전과 생존 확보 및 위험 관리가 사회 운영의 중심이 된 상태를 위험사회라고 명명한다."
    },
    {
      "id": "R21",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "위험사회의 개념 설명에서 위험 대응 능력과 분배의 계층적 불평등이라는 새로운 논점으로 나아간다."
    },
    {
      "id": "R22",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "위험이 모두에게 위협이 된다고 해서 대응 능력까지 평등한 것은 아니라는 한계를 제시한다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "계층별 위험 대응 능력이 다르다는 사실이 위험 역시 불평등하게 분배된다는 판단을 뒷받침한다."
    },
    {
      "id": "R24",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "위험사회의 개념 설명에서 과학·전문가의 권위와 위험 관리 구조의 변화로 논의를 확장한다."
    },
    {
      "id": "R25",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과학의 위험 생산 관여가 위험 정의와 관리에 관한 독점적 권한을 상실하게 하는 원인으로 제시된다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과학이 위험을 완전히 통제하지 못하는 것이 독점적 관리 권한의 상실을 일으키는 원인으로 제시된다."
    },
    {
      "id": "R27",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과학의 독점적 권한 상실이 과학적 지식에 기반한 전문가 권위의 해체로 이어진다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "전문가 권위가 해체됨에 따라 위험 관리 구조가 시민 참여의 하위정치 중심으로 전환된다."
    },
    {
      "id": "R29",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "기존 구조를 점검하고 재구성하는 성찰적 근대성이 위험 극복과 안전한 삶을 이루기 위한 수단으로 제시된다."
    },
    {
      "id": "R30",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "위험사회가 제기하는 안전과 생존의 문제에 성찰적 근대성을 대응 방안으로 제시한다."
    },
    {
      "id": "R31",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "기든스는 전문가 체계에 대한 믿음의 유지 기능을, 벡은 전문가 권위의 해체를 강조하며 서로 다른 견해를 보인다."
    },
    {
      "id": "R32",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "두 이론 모두 인간을 기존 구조에 순응하기만 하는 존재가 아니라 구조를 점검하고 재구성하는 주체로 본다."
    },
    {
      "id": "R33",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "두 이론의 의의를 나란히 제시하면서 기든스는 불확실성 속 인간의 주체성에, 벡은 위험 극복과 안전 확보의 가능성에 초점을 둔다."
    }
  ]
}

